function validate(input) {
  const [{ Patients = [] }] = input;
  const ids = new Set();
  for (const [id, , conditions] of Patients) {
    if (id === null || ids.has(id)) return 'Every patient needs a unique patient_id.';
    ids.add(id);
    if (conditions === null || !/^([^ ]+( [^ ]+)*)?$/.test(conditions)) return `Patient ${id}'s conditions must be codes separated by single spaces.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const codes = ['DIAB100', 'DIAB101', 'DIAB1', 'DIAB10X', 'DIAB201', 'DIAB2', 'DIAB', 'SADIAB100', 'XDIAB1', 'ACNE', 'COUGH', 'YFEV', 'MYOP'];
  const names = ['Daniel', 'Alice', 'Bob', 'George', 'Alain', 'Mia', 'Omar', 'Lena'];
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const Patients = [];
  for (let id = 1; id <= count; id++) {
    const parts = Array.from({ length: Math.floor(rand() * 4) }, () => codes[Math.floor(rand() * codes.length)]);
    Patients.push([id, names[Math.floor(rand() * names.length)], parts.join(' ')]);
  }
  return [{ Patients }];
}
